<template><section class="analysis"><h3>{{ result?.source_mode==='reference'?'所在段落译文':'参考译文' }}</h3><template v-if="result"><p v-if="result.range_note" class="info-box">{{ result.range_note }}</p><p>{{ result.literal }}</p><template v-if="result.natural"><h4>意译</h4><p>{{ result.natural }}</p></template><div v-if="result.key_points?.length" class="definition"><h4>理解要点</h4><p v-for="item in result.key_points" :key="item.text"><b>{{ item.text }}</b>：{{ item.explanation }}</p></div><p class="result-source">{{ result.source_label || 'AI 生成内容，请结合原文核对' }}</p></template><p v-else class="empty">请选择原文后查看译文。</p></section></template>
